/**
 * Trello Node - Version 1
 * Discriminator: resource=cardComment, operation=update
 */


interface Credentials {
  trelloApi: CredentialReference;
  trelloOAuth1Api: CredentialReference;
}

/** Update a board */
export type TrelloV1CardCommentUpdateParams = {
  resource: 'cardComment';
  operation: 'update';
  authentication?: 'apiKey' | 'oAuth1' | Expression<string>;
/**
 * The ID of the card
 * @searchListMethod searchCards
 * @default {"mode":"list","value":""}
 */
    cardId?: { __rl: true; mode: 'list' | 'url' | 'id'; value: string; cachedResultName?: string };
/**
 * The ID of the comment to delete
 */
    commentId: string | Expression<string>;
/**
 * Text of the comment
 */
    text: string | Expression<string>;
};

export type TrelloV1CardCommentUpdateNode = {
  type: 'n8n-nodes-base.trello';
  version: 1;
  config: NodeConfig<TrelloV1CardCommentUpdateParams> & { credentials?: Credentials };
};